-- Expanded town places (generated by scripts/expand-town.ts).
on conflict (id) do update set name=excluded.name, layout_x=excluded.layout_x, layout_y=excluded.layout_y;

on conflict (slug) do update set name=excluded.name, is_active=true, map_coordinate_mode='virtual_game', canvas_x=excluded.canvas_x, canvas_y=excluded.canvas_y;
